WFJ.Data.add("spell", {
  [1220000] = { "Le tue mosse d'apertura hanno una probabilità del $N1% di azzerare il costo in energia della tua prossima abilità.", nil, 0xd6c7f4c4, nil, "um" },
  [1220002] = { "Aumenta del $N1% i danni inflitti dall'arma nella mano primaria con le abilità che generano punti combo.", nil, 0xd6c7f64c, nil, "um" },
  [1220004] = { "Riduce il tempo di recupero di Sparizione a $D1. Non cumulabile con Elusività.", nil, 0xd6c7f64e, nil, "um" },
  [1220010] = { "Aumenta del $N1% la tua probabilità di infliggere un colpo critico con i pugnali.", nil, 0xd6e97acb, nil, "um" },
  [1220012] = { "Aumenta la probabilità di critico di Imboscata del $N1%.", nil, 0xd6e97acd, nil, "um" },
  [1220016] = { "Mentre Just a Flesh Wound e Lame Danzanti sono attivi, Tempesta Cremisi, Schioppo e Ventaglio di Lame costano $N1 energia in meno e generano il $N2% di minaccia in più.", nil, 0xc539345c, nil, "um" },
  [1220018] = { "Sparizione ora riduce del $N1% tutti i danni magici che subisci per tutta la sua durata, ma non conferisce più Furtività e non rimuove più gli effetti che riducono il movimento.", nil, 0xc539775c, nil, "um" },
  [1220020] = { "Le tue mosse risolutive hanno una probabilità del $N1% per punto combo di farti subire il $N2% di danni fisici in meno dal prossimo attacco in mischia che ti colpisce entro $D1.", nil, 0xc5397866, nil, "um" },
  [1220022] = { "Il tuo Rolling with the Punches ora si attiva anche ogni volta che ottieni un punto combo.", nil, 0xd6c7f6ce, nil, "um" },
  [1220023] = { "Il tuo Rolling with the Punches ti conferisce anche il $N1% di Armatura in più dagli oggetti per accumulo (fino a un massimo del $N2%).", nil, 0xd6c7f95e, nil, "um" },
  [1220026] = { "Il tempo di recupero del tuo Doppio Attacco si azzera ogni volta che il tuo bersaglio schiva o para.", nil, 0xd6c837c8, nil, "um" },
  [1220032] = { "Lifetap genera il $N1% di mana in più e il $N2% di minaccia in meno.", nil, 0xc539ba6d, nil, "um" },
  [1220034] = { "Aumenta del $N1% la tua probabilità di critico con incantesimi e attacchi.", nil, 0xc539ba6e, nil, "um" },
  [1220035] = { "La probabilità di attivazione del tuo talento Notte Fonda aumenta del $N1%. Il tuo Incenerimento ha una probabilità del $N2% di attivare Decimazione indipendentemente dalla salute del bersaglio.", nil, 0xc539baeb, nil, "um" },
  [1220038] = { "Aumenta del $N1% i danni dei tuoi incantesimi periodici e della tua vilguardia.", nil, 0xd6c87b58, nil, "um" },
  [1220040] = { "I danni periodici dei tuoi incantesimi Ombrofuoco, Afflizione Instabile e Maledizione dell'Agonia e i danni inflitti dalla tua vilguardia hanno una probabilità del $N1% di conferire l'effetto Shadow Trance.", nil, 0xd6c87ee9, nil, "um" },
  [1220042] = { "Dardo d'Ombra infligge il $N1% di danni in più per ogni tuo effetto che affligge il bersaglio, fino a un massimo del $N2%.", nil, 0xd6c87eee, nil, "um" },
  [1220048] = { "Aumenta del $N1% la potenza d'attacco e i danni magici che il tuo famiglio demoniaco ottiene dalle tue caratteristiche.", nil, 0xd6e97b4e, nil, "um" },
  [1220050] = { "Aumenta del $N1% i benefici del tuo talento Master Demonologist.", nil, 0xd6e97b4f, nil, "um" },
  [1220052] = { "Esilio ora è istantaneo e puoi lanciarlo su te stesso quando sei un demone. Non puoi esiliarti mentre hai Rigorosità, e farlo ti applica Rigorosità per $D1.", nil, 0xc539bbef, nil, "um" },
  [1220054] = { "Ogni volta che subisci danni, tu e il tuo famiglio ottenete mana pari ai danni subiti, fino a un massimo di $N1 mana per evento. Può avvenire solo una volta ogni pochi secondi.", nil, 0xc539bbf0, nil, "um" },
  [1220056] = { "I colpi di Fendente d'Ombra hanno una probabilità del $N1% di conferirti un frammento d'anima, azzerare il tempo di recupero di Fuoco dell'Anima e rendere istantaneo il tuo prossimo Fuoco dell'Anima lanciato entro $D1.", nil, 0xc539fd70, nil, "um" },
  [1220058] = { "Mentre hai come bersaglio un nemico entro $N1 m, Conversione Vitale ti conferisce mana a spese della salute del bersaglio, ma gli infligge il $N2% di danni in meno. Il mana ottenuto resta invariato.", nil, 0xd6e86e26, nil, "um" },
  [1220060] = { "Mentre Metamorfosi è attiva, le tue abilità offensive e le evocazioni di demoni non costano frammenti d'anima. Inoltre, ti curi del $N1% della tua salute massima quando danneggi un bersaglio con Combustione dell'Ombra.", nil, 0xd6e86f2a, nil, "um" },
  [1220062] = { "Le cure in eccesso che ricevi da te stesso vengono convertite in uno scudo che assorbe i danni. Questo scudo può assorbire fino al $N1% della tua salute massima e si accumula con più cure.", nil, 0xd6e8702b, nil, "um" },
  [1220070] = { "Generi il $N1% di minaccia in più per $D1 dopo aver usato Tiro Distraente.", nil, 0xc516e63c, nil, "um" },
  [1220072] = { "Mentre segui le tracce di un tipo di creatura, infliggi il $N1% di danni in più a quel tipo di creatura.", nil, 0xc5393351, nil, "um" },
  [1220074] = { "La tua prossima abilità di tiro usata entro $D1 dopo Tiro Mirato infligge il $N2% di danni in più.", nil, 0xc516e84a, nil, "um" },
  [1220086] = { "Aumenta del $N1% la potenza d'attacco che il tuo famiglio bestia ottiene dalle tue caratteristiche.", nil, 0xd6e979c6, nil, "um" },
  [1220088] = { "Aumenta del $N1% la rigenerazione di Focus del tuo famiglio bestia.", nil, 0xd6e979c7, nil, "um" },
  [1220092] = { "Morso della Mangusta riduce anche del $N1% la probabilità di schivata del bersaglio e aumenta del $N2% la tua probabilità d'impatto per $D1.", nil, 0xc516e8cd, nil, "um" },
  [1220094] = { "Morso della Mangusta si attiva anche per $D1 ogni volta che il bersaglio para o blocca o quando il tuo attacco in mischia va a vuoto.", nil, 0xc516e94b, nil, "um" },
  [1220106] = { "-$D1 al tempo di lancio di Cura Rapida e -$D2 al tempo di lancio di Cura Maggiore.", nil, 0xc5176ccf, nil, "um" },
  [1220108] = { "Aumenta del $N1% la tua probabilità di critico con incantesimi e attacchi.", nil, 0xc5176cd0, nil, "um" },
  [1220110] = { "Aumenta del $N1% la tua probabilità di critico con Preghiera di Cura e Circolo di Guarigione.", nil, 0xc5176cd1, nil, "um" },
  [1220112] = { "Permette al $N1% della rigenerazione del mana di continuare durante il lancio di incantesimi.", nil, 0xd6c7703c, nil, "um" },
  [1220114] = { "Le tue cure periodiche hanno una probabilità del $N1% di rendere istantaneo il tuo prossimo incantesimo con un tempo di lancio inferiore a $N2 s.", nil, 0xd6c770ba, nil, "um" },
  [1220116] = { "Circolo di Guarigione e Contrizione applicano anche ai loro bersagli un effetto di cura periodica che cura del $N1% di tale quantità in $D1.", nil, 0xd6c772c8, nil, "um" },
  [1220122] = { "Riduce il tempo di recupero di Contrizione di $D1.", nil, 0xd6e97ac8, nil, "um" },
  [1220124] = { "Aumenta del $N1% i danni assorbiti dal tuo incantesimo Parola del Potere: Scudo.", nil, 0xd6e97ac9, nil, "um" },
  [1220126] = { "Puoi lanciare Cura Rapida in Forma d'Ombra.", nil, 0xc5176cd2, nil, "um" },
  [1220128] = { "I colpi critici di Detonazione Mentale riducono del $N1% la durata del tuo prossimo Flagello Mentale, aumentandone del $N2% i danni totali.", nil, 0xc5393352, nil, "um" },
  [1220130] = { "Riduce il tempo di recupero di Parola d'Ombra: Morte di $D1.", nil, 0xd6c7b1b7, nil, "um" },
  [1220132] = { "La tua Parola d'Ombra: Dolore ha una probabilità del $N1% per punto talento in Spirit Tap di attivare il tuo talento Spirit Tap quando infligge danni, o del $N2% per punto talento quando un bersaglio muore con la tua Parola d'Ombra: Dolore attiva. Anche Concentrazione Interiore ha una probabilità del $N3% per punto talento di attivare Spirit Tap.", nil, 0xd6c7b1bb, nil, "um" },
  [1220134] = { "Mentre Spirit Tap è attivo, infliggi il $N1% di danni da ombra in più.", nil, 0xd6c7b2bd, nil, "um" },
  [1220142] = { "I tuoi Temporal Beacon durano il $N1% in più.", nil, 0xc51727b9, nil, "um" },
  [1220144] = { "Aumenta del $N1% tutte le cure cronomantiche che effettui.", nil, 0xc5172b51, nil, "um" },
  [1220146] = { "Ogni volta che curi un bersaglio con Rigenerazione, il tempo di recupero rimanente di Riavvolgimento Temporale si riduce di $D1.", nil, 0xc5172bce, nil, "um" },
  [1220150] = { "Detonazione Arcana ottiene una probabilità aggiuntiva del $N1% di attivare Raffica di Missili, e Raffica di Missili ora influisce su Rigenerazione come su Missili Arcani.", nil, 0xd6c72ba6, nil, "um" },
  [1220152] = { "I tuoi Temporal Beacon applicati da Rigenerazione di Massa ora durano $D1.", nil, 0xd6c73040, nil, "um" },
  [1220158] = { "Aumenta di un ulteriore $N1% la probabilità di attivare la tua runa Dita di Gelo.", nil, 0xd6e97a47, nil, "um" },
  [1220160] = { "Aumenta del $N1% i danni inflitti dai tuoi incantesimi Dardo di Gelo e Dardo di Geloincanto.", nil, 0xd6e97a49, nil, "um" },
  [1220162] = { "Sei immune a tutti i danni mentre canalizzi Evocazione.", nil, 0xc516e94d, nil, "um" },
  [1220164] = { "Ottieni il $N1% di danni in più per $D1 ogni volta che lanci un incantesimo di una scuola di magia diversa.", nil, 0xc516e94f, nil, "um" },
  [1220166] = { "Armatura Magica aumenta di un ulteriore $N1% la tua rigenerazione del mana durante il lancio. Armatura Lavica aumenta di $N2 i tuoi danni magici e le tue cure. Armatura di Ghiaccio aumenta del $N3% la probabilità di attivare Dita di Gelo.", nil, 0xc51727b7, nil, "um" },
  [1220180] = { "Aumenta l'indice di blocco con lo scudo di $N1.", nil, 0xc5176c4d, nil, "um" },
  [1220182] = { "Ti curi di $N1 quando blocchi. La cura può avvenire solo una volta ogni pochi secondi.", nil, 0xc5176c4f, nil, "um" },
  [1220184] = { "Scudo Benedetto non ha più cariche e dura sempre per tutta la sua durata. Inoltre, i suoi danni aumentano del $N1% del tuo indice di blocco con lo scudo.", nil, 0xc5176ccb, nil, "um" },
  [1220186] = { "Aumenta del $N1% la probabilità di blocco aggiuntiva conferita da Scudo Benedetto.", nil, 0xd6c77034, nil, "um" },
  [1220188] = { "Subisci il $N1% di danni in meno mentre Scudo Benedetto è attivo.", nil, 0xd6c77035, nil, "um" },
  [1220190] = { "Il tuo talento Regolamento di Conti ora ha una probabilità del $N1% per punto talento di attivarsi quando blocchi.", nil, 0xd6c77039, nil, "um" },
  [1220196] = { "Aumenta al $N1% la probabilità che gli alleati attivino il tuo Judgement of Light o Judgement of Wisdom.", nil, 0xc5172bd5, nil, "um" },
  [1220198] = { "Aumenta del $N1% la tua probabilità di critico con incantesimi e attacchi.", nil, 0xc5393350, nil, "um" },
  [1220200] = { "Ogni volta che Lampo di Luce, Luce Sacra o Faro di Luce curano un bersaglio fino alla salute piena, curi anche tutti i membri del suo gruppo di $N1 salute.", nil, 0xc5172c52, nil, "um" },
  [1220202] = { "Aumenta del $N1% la probabilità di critico di Folgore Sacra.", nil, 0xd6c76eb0, nil, "um" },
  [1220204] = { "Aumenta del $N1% i danni inflitti dalla tua Consacrazione.", nil, 0xd6c76eb1, nil, "um" },
  [1220206] = { "Quando non sei tu il bersaglio del tuo Faro di Luce, anche il bersaglio del tuo Faro di Luce viene curato del $N1% dei danni che infliggi con Consacrazione, Esorcismo, Folgore Sacra, Ira Sacra e Martello dell'Ira.", nil, 0xd6c76f30, nil, "um" },
  [1220212] = { "I tuoi Judgement of Light e Judgement of Wisdom conferiscono anche gli effetti di Giudizio del Crociato.", nil, 0xc5172c54, nil, "um" },
  [1220214] = { "Sigillo del Comando, Sigillo della Rettitudine, Seal of Martyrdom e Luce Solare infliggono il $N1% di danni in meno, ma ora persistono per $N2 s dopo che hai lanciato un altro sigillo, o finché non ne lanci un terzo. I tuoi Giudizi ora possono attivare più sigilli, se sono attivi.", nil, 0xc5176c4a, nil, "um" },
  [1220216] = { "Aumenta del $N1% i danni inflitti dai tuoi Giudizi offensivi e i tuoi Giudizi non consumano più i Sigilli sul bersaglio. I tuoi Giudizi ora possono attivare più Sigilli, se attivi.", nil, 0xd6c76f35, nil, "um" },
  [1220218] = { "Riduce il tempo di recupero di Giudizio di $D1, ma riduce del $N2% i danni inflitti dai tuoi Giudizi.", nil, 0xd6c76fb6, nil, "um" },
  [1220220] = { "Il tuo Giudizio aumenta i danni da sacro del $N1% per $D1, effetto che si accumula fino a $N3 volte.", nil, 0xd6c76fb9, nil, "um" },
  [1220226] = { "Aumenta del $N1% i danni inflitti dal tuo incantesimo Folgore Sacra.", nil, 0xd6e97a4a, nil, "um" },
  [1220228] = { "Riduce il tempo di recupero di Esorcismo di $D1 e ne aumenta i danni inflitti del $N2%.", nil, 0xd6e97ac6, nil, "um" },
  [1220232] = { "Aumenta del $N1% la tua velocità d'attacco per i tuoi prossimi $N2 colpi dopo aver parato, schivato o bloccato.", nil, 0xc539ba65, nil, "um" },
  [1220234] = { "Le tue parate e schivate attivano anche l'abilità della runa Maestria nello Scudo.", nil, 0xc539ba66, nil, "um" },
  [1220236] = { "Il tuo Totem della Pelle di Pietra riduce anche del $N1% i danni fisici subiti e il tuo Windwall Totem riduce anche del $N2% i danni magici subiti.", nil, 0xc539ba69, nil, "um" },
  [1220238] = { "La tua Folgore del Fuoco aumenta anche del $N1% la probabilità di blocco per $D1 o finché non blocchi un attacco.", nil, 0xd6c83be6, nil, "um" },
  [1220240] = { "Ogni volta che blocchi, il valore di blocco aumenta del $N1% dei tuoi danni magici per $D1, effetto che si accumula fino a $N3 volte.", nil, 0xd6c87ad7, nil, "um" },
  [1220242] = { "Ogni volta che blocchi un attacco, hai una probabilità del $N1% di attivare la tua runa Arma del Maelstrom.", nil, 0xd6c87b57, nil, "um" },
  [1220248] = { "Il raggio dei tuoi totem che hanno effetto sui bersagli amici aumenta a $N1 m.", nil, 0xc53978ea, nil, "um" },
  [1220250] = { "Dopo aver lanciato Ondata di Cura, Ondata di Cura Inferiore o Marea Gelida, hai una probabilità del $N1% di ottenere mana pari al $N2% del costo base dell'incantesimo.", nil, 0xc53978ed, nil, "um" },
  [1220252] = { "La tua Ondata di Cura ora rimbalza su altri bersagli vicini. Ogni rimbalzo riduce del $N1% l'efficacia della cura, e l'incantesimo rimbalza su un massimo di $N2 bersagli aggiuntivi.", nil, 0xc53979ef, nil, "um" },
  [1220254] = { "I tuoi colpi critici non periodici di danno e di cura ora hanno una probabilità del $N1% di attivare il tuo Scudo d'Acqua, senza consumarne una carica né attivarne il tempo di recupero.", nil, 0xd6c837c9, nil, "um" },
  [1220256] = { "La tua Catena di Fulmini ora cura anche il bersaglio del tuo Scudo di Terra più recente del $N1% dei danni inflitti.", nil, 0xd6c837ce, nil, "um" },
  [1220258] = { "Aumenta del $N1% le cure di Catena di Guarigione e i danni di Catena di Fulmini.", nil, 0xd6c8384c, nil, "um" },
  [1220264] = { "Aumenta del $N1% la tua probabilità di critico con incantesimi e attacchi.", nil, 0xc539b9e2, nil, "um" },
  [1220266] = { "Il tuo talento Raffica di Colpi aumenta la tua velocità d'attacco di un ulteriore $N1%.", nil, 0xc539b9e4, nil, "um" },
  [1220268] = { "La tua probabilità di attivare Folgore Statica aumenta del $N1% (del $N2% se combatti con due armi).", nil, 0xd6c83b61, nil, "um" },
  [1220270] = { "Aumenta del $N1% i danni con la mano primaria inflitti dal tuo Assalto della Tempesta.", nil, 0xd6c83b63, nil, "um" },
  [1220272] = { "Mentre Folgore Statica è incisa, il tuo Scudo di Fulmini ottiene una carica ogni volta che colpisci un bersaglio con Dardo Fulminante o Catena di Fulmini, fino a un massimo di $N1 cariche. Inoltre, mentre Folgore Statica è incisa, il tuo Scudo di Fulmini può infliggere danni critici.", nil, 0xd6c83bdf, nil, "um" },
  [1220278] = { "I colpi critici del tuo Dardo Fulminante hanno una probabilità del $N1% di azzerare il tempo di recupero di Getto di Lava e Catena di Fulmini e di rendere istantaneo il prossimo Getto di Lava o Catena di Fulmini lanciato entro $D1.", nil, 0xc539b95f, nil, "um" },
  [1220279] = { "Getto di Lava ora riporta anche la durata di Folgore del Fuoco sul tuo bersaglio a $D1.", nil, 0xc539b963, nil, "um" },
  [1220282] = { "I tuoi colpi critici magici ora hanno una probabilità del $N1% di attivare il tuo talento Focus Elementale.", nil, 0xd6c83850, nil, "um" },
  [1220284] = { "Loyal Beta della tua abilità Spirit of the Alpha ora aumenta anche del $N1% i danni da fuoco, da gelo e da natura.", nil, 0xd6c838ce, nil, "um" },
  [1220286] = { "Mentre Lancio Istintivo è attivo, infliggi il $N1% di danni non fisici in più.", nil, 0xd6c83ada, nil, "um" },
  [1220295] = { "Aumenta la probabilità di bloccare gli attacchi con lo scudo del $N1%.", nil, 0xd6e97b49, nil, "um" },
  [1220297] = { "Aumenta di un ulteriore $N1% la probabilità di attivare la tua runa Picco Energetico.", nil, 0xd6e97b4d, nil, "um" },
  [1220299] = { "Puoi lanciare Pronto Ritorno e Innervazione in Forma d'Orso o in Dire Bear Form.", nil, 0xc516e5b7, nil, "um" },
  [1220301] = { "Riduce di $D1 il tempo di recupero di Rabbia, che non riduce più la tua Armatura.", nil, 0xc516e5ba, nil, "um" },
  [1220303] = { "La Forma d'Orso e la Dire Bear Form aumentano di un ulteriore $N1% tutta la minaccia che generi, e Cower ora elimina tutta la tua minaccia verso il bersaglio, ma il suo tempo di recupero è più lungo di $D1.", nil, 0xc516e637, nil, "um" },
  [1220316] = { "Quando lanci Innervazione su un altro giocatore, viene lanciata anche su di te.", nil, 0xc5166339, nil, "um" },
  [1220318] = { "Lanciare Tocco Curativo o Nutrizione ti dà una probabilità del $N1% di ottenere mana pari al $N2% del costo base dell'incantesimo.", nil, 0xc516a2ab, nil, "um" },
  [1220320] = { "Riduce del $N1% il tempo di recupero di Tranquillità e ne aumenta le cure del $N2%.", nil, 0xc516e5b4, nil, "um" },
  [1220332] = { "Il tuo Fuoco Fatato (Feral) aumenta anche del $N1% la probabilità d'impatto di tutti gli attacchi contro quel bersaglio per $D1.", nil, 0xc4f5e954, nil, "um" },
  [1220334] = { "I danni periodici di Graffio e Squarcio ora possono essere critici.", nil, 0xc4f5e9d5, nil, "um" },
  [1220336] = { "I tuoi Squarcio e Morso Feroce hanno una probabilità del $N1% per punto combo speso di riportare la durata di Ruggito Selvaggio al valore iniziale.", nil, 0xc4f5e9d6, nil, "um" },
  [1220348] = { "Danni inflitti da Spine aumentati del $N1% e durata aumentata del $N2%.", nil, 0xc4f5e8cf, nil, "um" },
  [1220350] = { "Aumenta la probabilità d'impatto con incantesimi e attacchi del $N1%.", nil, 0xc4f5e8d5, nil, "um" },
  [1220352] = { "Riduce del $N1% il tempo di recupero di Pioggia di Stelle.", nil, 0xc4f5e8d6, nil, "um" },
  [1220364] = { "Riduce il tempo di lancio e il tempo di recupero globale di Fuoco Stellare di $D1.", nil, 0xd6e979c4, nil, "um" },
  [1220366] = { "Aumenta la probabilità di critico di Ira Silvana del $N1%.", nil, 0xd6e979c5, nil, "um" },
